<?php

declare(strict_types=1);

final class CoreProjectTemplateCatalog
{
    public function templateComposerJson(array $vars): string
    {
        $composer = [
            'name' => 'local/' . strtolower(str_replace(' ', '-', $vars['project_name'])),
            'description' => 'Robust Flight PHP starter generated by install-flight-starter.php',
            'type' => 'project',
            'require' => [
                'php' => '^8.1',
                'flightphp/core' => '^3.14',
                'google/apiclient' => '^2.18',
                'league/oauth2-client' => '^2.8',
                'league/oauth2-github' => '^3.1',
                'stripe/stripe-php' => '^16.6',
                'symfony/mailer' => '^7.3',
                'symfony/mime' => '^7.3',
            ],
            'autoload' => [
                'psr-4' => [
                    $vars['namespace'] . '\\' => 'app/',
                ],
                'files' => [
                    'app/Support/helpers.php',
                ],
            ],
            'scripts' => [
                'start' => 'php -S localhost:8000 -t public public/index.php',
                'migrate' => 'php app/Console/console.php migrate',
                'rollback' => 'php app/Console/console.php rollback',
                'seed' => 'php app/Console/console.php seed',
                'queue:work' => 'php app/Console/console.php queue:work',
                'assets:build' => 'npm run build',
            ],
            'minimum-stability' => 'stable',
            'prefer-stable' => true,
        ];

        return json_encode($composer, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES) ?: '{}';
    }

    public function templateGitignore(): string
    {
        return <<<'TEXT'
/vendor/
/node_modules/
/.env
/app/storage/*.sqlite
/app/storage/*.db
/app/storage/logs/*.log
/app/storage/cache/*
!/app/storage/cache/.gitkeep
/app/storage/queue/*
!/app/storage/queue/.gitkeep
/public/build/*
!/public/build/.gitkeep
TEXT;
    }

