    public function templateReadme(array $vars, InstallerFeatures $features): string
    {
        $stack = [
            '- PHP 8.1+',
            '- Flight PHP',
            '- SQLite by default',
            '- MVC structure with routes, services and console commands',
            '- Database migrations and queue worker',
            '- Session auth, Google/GitHub OAuth, Stripe billing, SEO module and middleware pipeline included',
        ];

        if ($features->backoffice) {
            $stack[] = '- BackOffice CRUD generator';
        }

        if ($features->frontend) {
            $stack[] = '- ViteJS and TailwindCSS ready through `resources/`';
        }

        $adminBlock = $features->backoffice
            ? "- Admin dashboard: `{$vars['admin_path']}`\n- Default admin seed: `{$vars['admin_email']}` / `{$vars['admin_password']}`\n"
            : '';

        $frontendBlock = $features->frontend
            ? "- Asset pipeline via `vite.config.js`, `tailwind.config.js` and `resources/js/app.js`\n"
            : '';

        $structureLines = [
            '- `app/` application code',
            '- `app/config/` configuration files',
            '- `app/routes/` routes web, api and admin générées',
            '- `app/storage/` logs, queue runtime and SQLite database',
            '- `app/Views/` vues MVC côté serveur',
            '- `public/` front controller and web entry point',
        ];

        if ($features->frontend) {
            $structureLines[] = '- `resources/` sources frontend Vite (`css/`, `js/`)';
        }

        $featureLines = [
            '- MVC base with `HomeController`',
            '- `View`, `Database`, `Migrator` and queue services',
            '- `Auth`, `Mailer`, `SeoManager`, `StripeBilling`, `GoogleOAuth`, `GithubOAuth` and a reusable middleware pipeline',
            '- `Generator` service for code scaffolding',
            '- `CrudGenerator` service for admin CRUD generation',
            '- `/api/health` endpoint',
            '- Frontend auth routes with Google/GitHub login, Stripe pricing/checkout/webhook endpoints, billing history tables, account page, sitemap and robots endpoints',
        ];

        if ($frontendBlock !== '') {
            $featureLines[] = rtrim($frontendBlock);
        }

        if ($adminBlock !== '') {
            foreach (explode("\n", trim($adminBlock)) as $line) {
                if ($line !== '') {
                    $featureLines[] = $line;
                }
            }
        }

        $stackText = implode("\n", $stack);
        $structureText = implode("\n", $structureLines);
        $featureText = implode("\n", $featureLines);

        return <<<TEXT
# {$vars['project_name']}

Starter Flight PHP generated by `install-flight-starter.php`.

## Stack

$stackText

## Structure

$structureText

## Install

```bash
composer install
npm install
cp .env.example .env
npm run build
php app/Console/console.php migrate
php app/Console/console.php seed
php -S localhost:8000 -t public public/index.php
```

## Commands

```bash
php app/Console/console.php migrate
php app/Console/console.php rollback
php app/Console/console.php seed
php app/Console/console.php queue:dispatch App\\Jobs\\ExampleJob '{"message":"hello"}'
php app/Console/console.php queue:dispatch App\\Jobs\\SendMailJob '{"to":"hello@example.com","subject":"Welcome","html":"<h1>Hello</h1>"}'
php app/Console/console.php queue:work --once
php app/Console/console.php make:controller ReportsController
php app/Console/console.php make:model Report
php app/Console/console.php make:migration create_reports_table
php app/Console/console.php make:job SendDigestJob
php app/Console/console.php make:backoffice posts title:string content:text
npm run dev
npm run build
```

## Features

$featureText
## Development notes

- The queue uses the database table `{$vars['queue_table']}`.
- The SQLite database lives at `{$vars['sqlite_database']}`.
- Stripe and social login providers are shipped disabled by default until their env keys are filled.
- `app/config/billing.php` contains the starter plan catalog to adapt to your Stripe product setup.
- `app/routes/admin_generated.php` is extended by `make:backoffice`.
TEXT;
    }

    public function templatePublicIndex(): string
    {
        return <<<'PHP'
<?php

declare(strict_types=1);

define('APP_CONTEXT', 'web');

require dirname(__DIR__) . '/app/bootstrap.php';

\Flight::start();
PHP;
    }

    public function templateHtaccess(): string
    {
        return <<<'TEXT'
RewriteEngine On
RewriteCond %{REQUEST_FILENAME} !-f
RewriteCond %{REQUEST_FILENAME} !-d
RewriteRule ^ index.php [QSA,L]
TEXT;
    }
}